from pathlib import Path
import json
from design import DATA, LEVEL, DEPTH, calc

D=Path(__file__).resolve().parent
out=D.parent/'due-camere'
def it(v):return f'{v:.2f}'.replace('.',',')
sources=[
 ('RET 2023 · art. 95, comma 12','https://san-gregorio-di-catania-api.municipiumapp.it/s3/6258/allegati/prg/ret-con-emendamenti-commissione-consiliare_2023.pdf'),
 ('Regolamento pubblicato con il PRG · art. 2, caratteristiche dei locali','https://san-gregorio-di-catania-api.municipiumapp.it/s3/6258/allegati/prg/regolamento_edilizio.pdf'),
 ('D.M. 5 luglio 1975 · artt. 1, 2 e 5','https://www.prefettura.it/FILES/AllegatiPag/1164/07.06.2023_T_14_D.M._Sanit__05_luglio_1975-posti_CAS.pdf')]
titles={'F':'Due soppalchi sopra locali in uso','L':'Due camere sopra basi chiuse'}
intro={'F':'In pianta entrano due singole. A quota +2,92 m rimangono appena 1,28 m sopra se il soffitto è a 4,20 m. Con le altezze documentate scarterei F per il pernottamento.','L':'È la prima sezione che farei misurare. A +1,08 m, con un soffitto a 4,20 m, restano 3,12 m sopra. Sotto ciascuna camera rimangono 90 cm per contenimento e si rinuncia all’uso abituale di quel pavimento.'}
program={'F':'Sotto la camera sulla piazza rimane una matrimoniale di circa 1,58 × 2,01 m. Sotto quella sul retro continua la zona giorno. La terza camera è il programma messo alla prova, non una potenzialità dimostrata.','L':'Due singole rialzate sostituiscono la matrimoniale. Il pranzo rimane nella campata centrale, il cuneo serve da guardaroba e il giardino d’inverno resta subordinato alle verifiche del terrazzo.'}
obstacles={'F':'La rampa del retro incrocia la quinta vetrata e il collegamento con la cucina. Sul fronte verificare il passaggio sotto l’ultima rampa, la portafinestra e la svolta sul pianerottolo. L’altezza disponibile sopra non consente di entrare in piedi dove H è 4,20 m.','L':'Sul fronte la scala passa vicino alla soglia della porta; sul retro il primo gradino sfiora la proiezione del varco cucina. Rilevare luci finite, battenti, spazi di manovra e uscita prima di confermare queste posizioni.'}
light='La camera sulla piazza ha una vetrata interna arretrata rispetto alla portafinestra. Occorre dimostrare o ricavare un’apertura diretta verso l’esterno. Sul retro misurare quanta finestra apribile rimane sopra il nuovo pavimento e verificare l’effetto del giardino chiuso. Come riferimento, 1/8 del netto vale circa 1,13–1,19 m² per singola. Le piante non presuppongono nuove aperture in facciata o in copertura.'
reg='Il RET 2023, art. 95 c. 12, definisce il soppalco e richiama i requisiti igienico-sanitari e la disciplina locale. Il regolamento pubblicato col PRG, art. 2 punto 2 d), indica per gli impalcati a mezza altezza un minimo di 4,80 m, un massimo di un terzo del locale e 40 m³ nella porzione a tutta altezza. Lo stesso articolo tratta il recupero nei nuclei antichi. Il SUE deve chiarire quale disciplina si applichi a Palazzo Lombardo e come qualificare anche le basi chiuse di L.'
def version(v):
    figures=''
    for k,name in [('piazza','Sulla piazza'),('retro','Sul retro')]:
        area=it(calc(DATA[v][k])['net'])
        figures+=f'<figure><button class="picture" data-zoom="{v}-{k}.webp" aria-label="Ingrandisci camera {name.lower()}"><img src="{v}-{k}.webp" alt="Camera sezionata con letto singolo e scala propria"></button><div class="roomtitle"><h3>{name}</h3><span>{area} m² netti</span></div><figcaption>Letto 90 × 200 cm · sbarco escluso dal netto</figcaption></figure>'
    z=LEVEL[v]
    stats=''.join(f'<div><strong>{s} m</strong><small>{label}</small></div>' for s,label in [('+'+it(z),'Quota delle due camere'),(it(z-DEPTH[v]),'Libero sotto impalcato'),(it(4.20-z),'Sopra, se H locale = 4,20 m')])
    return f'<article data-version="{v}" {"" if v=="F" else "hidden"}><div class="verdict"><strong>{titles[v]}</strong><p>{intro[v]}</p></div><div class="rooms">{figures}</div><p class="small">Spaccati dello stesso modello della casa. Le due camere occupano le estremità opposte dell’appartamento. Due pareti sono sezionate per rendere visibili arredi e sbarchi.</p><div class="tools"><a class="btn primary" href="#visita">Esplora in 3D</a><a class="btn" href="#piante">Piante e sezioni</a><a class="btn" href="Due_camere_in_quota.pdf">Quaderno PDF</a></div><div class="stats">{stats}</div></article>'
head='''<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Due camere al piano alto · Casa Margherita</title><link rel="stylesheet" href="studio.css"><script defer src="visita.js"></script></head><body><header><a href="/">← Casa Margherita</a><span>ARCHAI / R05</span></header><main><div class="intro"><div><p class="over">Palazzo Lombardo · San Gregorio di Catania</p><h1>Due camere al piano alto</h1></div><p>Una verso la piazza e una verso il terrazzo. Ciascuna ha un letto singolo, un armadio e una scala indipendente. Il ripostiglio a cuneo resta al piano principale.</p></div><nav class="switch" aria-label="Distribuzioni"><a class="btn" href="?variante=F" data-v="F">F · Due soppalchi</a><a class="btn" href="?variante=L" data-v="L">L · Camere rialzate</a></nav>'''
viewer='''<section class="section" id="visita"><p class="over">Modello esplorabile</p><h2>Dal piano principale alle camere</h2><div class="tools"><button data-focus="tutte">Casa intera</button><button data-focus="alte">Solo camere e scale</button><button data-focus="piazza">Sulla piazza</button><button data-focus="retro">Sul retro</button><button id="roof">Mostra la copertura</button></div><div id="webgl"><p id="load" role="status">Apertura del modello…</p></div><p class="small">Trascina per ruotare. Le viste isolate aprono le pareti per mostrare i letti. Il comando copertura riporta l’intera casa e la forma ipotizzata delle volte.</p></section>'''
drawings='''<section class="section" id="piante"><p class="over">Disegni alla stessa scala</p><h2>Le due scale in pianta e in sezione</h2><div class="pair"><div><div class="tools"><button data-sheet="L1">Piano alto</button><button data-sheet="L0">Piano principale</button><button data-sheet="sezione">Sezione retro</button><button data-sheet="sezione-piazza">Sezione piazza</button></div><a id="sheetLink" target="_blank" rel="noopener"><img class="pane" id="sheet" alt="Tavola selezionata"></a><div class="downloads"><a id="dxf" download>Scarica il DXF</a><a id="svg" download>Scarica la tavola SVG</a></div></div><div class="notes"><h3>Distribuzione</h3><p id="prog"></p><h3>Passaggi da verificare</h3><p id="obstacles"></p><h3>Finestre e aria</h3><p>'''+light+'''</p><a id="fullRender" class="btn" target="_blank">Vista della casa intera</a><div class="downloads"><a id="inside1" target="_blank">Dal letto sulla piazza</a><a id="inside2" target="_blank">Dal letto sul retro</a></div></div></div></section>'''
checks='''<section class="section"><h2>Prima di contare due camere in più</h2><div class="pair"><div><p>Il disegno dimostra l’ingombro di due letti singoli. F conserva la matrimoniale inferiore; L la sostituisce. Per l’acquisto terrei aperto il conteggio finché rilievo e verifica del tecnico chiariscono altezze, luce, accessi e ammissibilità.</p><p>La singola sul fronte supera i 9 m² di appena 0,06–0,10 m². Due centimetri in meno lungo una parete possono cambiare l’esito. Per una matrimoniale il riferimento ordinario è 14 m².</p></div><div><table><thead><tr><th>Vano ospitante</th><th>1/3 del vano</th><th>Solo impalcato F</th></tr></thead><tbody><tr><td>Fronte · 20,8 m²</td><td>6,93 m²</td><td>10,06 m²</td></tr><tr><td>Intero salone · 39,9 m²</td><td>13,30 m²</td><td>10,53 m²</td></tr></tbody></table><p class="small">Il fronte supera già un terzo. Sul retro l’esito cambia includendo rampa e sbarco (circa 15,04 m²) o considerando solo la campata oltre la quinta. Il computo applicabile va chiarito con il Comune.</p></div></div><details><summary>Regolamenti e misure da chiedere</summary><p>'''+reg+'''</p><p>Rilevare imposta, chiave, altezza sui letti e su ogni gradino, luci apribili e spessori delle murature. Verificare i carichi fino agli appoggi sottostanti, la risposta sismica, le tutele storiche, l’accessibilità e i requisiti acustici.</p><p>'''+ ' · '.join(f'<a href="{u}">{t}</a>' for t,u in sources)+'''</p></details><div class="downloads"><a id="blend" download>Blender</a><a id="glb" download>GLB</a><a id="ifc" download>IFC</a><a href="Due_camere_in_quota.pdf">PDF</a><a href="https://github.com/Giulianomlodi/casa-margherita-22/releases/download/r05-due-camere/Casa_Margherita_R05.zip">Pacchetto R05</a></div></section></main><footer><a href="/#confronto">Tutte le proposte</a></footer><dialog id="zoom"><button id="close">Chiudi</button><img alt="Dettaglio della camera"></dialog></body></html>'''
(out/'index.html').write_text(head+version('F')+version('L')+viewer+drawings+checks,encoding='utf8')
(out/'testi.json').write_text(json.dumps({'programma':program,'passaggi':obstacles},ensure_ascii=False),encoding='utf8')
